/**
 * 主线任务官出现门禁：第 N 幕任务官必须等第 N-1 幕 **全部事件完成** 后才可出现在地图上。
 * 仅约束 giver（非 _enemy）；与 JSON appear 条件 AND 生效。
 */
import { isBattleEnemyNpcUid, type StoryEventLike } from './story-event-page-resolver';

export const STORY_RUNTIME_VERSION = '2026-07-04-audit-v4';

export function chainIndexFromNpcUid(npcUid: string): number | null {
  const m = npcUid.match(/chain_(\d+)/);
  return m ? Number(m[1]) : null;
}

export function findPriorMainlineGiverUid(
  npcUid: string,
  rows: Array<{ npcUid?: string }>,
): string | null {
  const idx = chainIndexFromNpcUid(npcUid);
  if (!idx || idx <= 1) return null;
  const want = `chain_${idx - 1}`;
  const prior = rows.find(
    (r) =>
      r.npcUid &&
      !isBattleEnemyNpcUid(r.npcUid) &&
      r.npcUid.includes(want) &&
      !r.npcUid.includes('_enemy'),
  );
  return prior?.npcUid ?? null;
}

export function isGiverChainFullyComplete(
  npcUid: string,
  events: StoryEventLike[] | null | undefined,
  isStepComplete: (uid: string, ev: StoryEventLike) => boolean,
): boolean {
  const list = events ?? [];
  if (!list.length) return true;
  return list.every((ev) => isStepComplete(npcUid, ev));
}

/** true = 仍应隐藏（上一幕主线未清完） */
export function isBlockedByPriorMainlineGiver(
  npcUid: string,
  rows: Array<{ npcUid?: string; events?: StoryEventLike[] }>,
  isStepComplete: (uid: string, ev: StoryEventLike) => boolean,
): boolean {
  if (isBattleEnemyNpcUid(npcUid)) return false;
  const priorUid = findPriorMainlineGiverUid(npcUid, rows);
  if (!priorUid) return false;
  const prior = rows.find((r) => r.npcUid === priorUid);
  if (!prior) return false;
  return !isGiverChainFullyComplete(priorUid, prior.events ?? [], isStepComplete);
}
